#pragma once
#include "api.hpp"
namespace snuw {
inline int apiTest(const fs::path& folder,const std::string& api){try{
 auto cfg=defaults(folder);cfg.update({{"api",api},{"api_key","native-test-key"},{"steps","3"},{"count","2"},{"width","832"},{"height","1216"},{"hires_enabled","켜기"},{"hires_steps","Steps와 동일"},{"channel_id","channel-test"},{"channel_name","방송 A"},{"learn_preferences",true},{"consistency_enabled",true},{"consistency_profile","aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa | Test Identity"},{"editing_model","chosen:latest"}});auto state=newState(cfg);state["drafts"]["prompt"]="한글 테스트, 1girl";auto ref=folder/"reference.png";if(fs::exists(ref))state["project"]["references"]=json::array({{{"path",utf8(ref.wstring())},{"role","character"},{"weight",0.6},{"end",0.8}}});auto e=new Engine;e->enqueue({"project-test",id(),cfg,state,false});bool finished=false,failed=false;int images=0;std::string reason;
 for(int i=0;i<400&&!finished;i++){for(auto& event:e->take()){if(event.kind=="image")images++;if(event.kind=="error"){failed=true;reason=event.text;finished=true;}if(event.kind=="done")finished=true;}std::this_thread::sleep_for(std::chrono::milliseconds(50));}e->stopping=true;e->cv.notify_one();if(e->worker.joinable())e->worker.join();delete e;if(!finished||failed||images!=2)throw std::runtime_error("배치 테스트 실패: "+reason+" images="+std::to_string(images));
 auto editing=cfg;editing.update({{"editing_image",utf8(ref.wstring())},{"editing_instruction","옷을 초록색으로"},{"editing_request",""},{"editing_session",""},{"editing_job",""}});e=new Engine;e->enqueue({"project-test",id(),editing,state,true});finished=false;failed=false;images=0;for(int i=0;i<400&&!finished;i++){for(auto& event:e->take()){if(event.kind=="image")images++;if(event.kind=="error"){failed=true;reason=event.text;finished=true;}if(event.kind=="done")finished=true;}std::this_thread::sleep_for(std::chrono::milliseconds(50));}e->stopping=true;e->cv.notify_one();if(e->worker.joinable())e->worker.join();delete e;if(!finished||failed||images!=1)throw std::runtime_error("편집 API 테스트 실패: "+reason);
 atomicWrite(folder/"native-api-result.json",json{{"ok",true},{"generation_images",2},{"edit_images",1},{"gui_opened",false}}.dump(2));return 0;
 }catch(const std::exception& e){atomicWrite(folder/"native-api-result.json",json{{"ok",false},{"error",e.what()}}.dump(2));return 1;}}
}
